  'scheduled_elevator_maintenance_notice': 'திட்டமிடப்பட்ட மின்தூக்கி பராமரிப்பு அறிவிப்பு',
  'elevators_in_block_a_b_will_undergo_quarterly_preventive_maintenance_this_saturday_from_10_am_to_1_pm': 'பிளாக் A மற்றும் B இல் உள்ள மின்தூக்கிகள் இந்த சனிக்கிழமை காலை 10 மணி முதல் மதியம் 1 மணி வரை காலாண்டு தடுப்பு பராமரிப்புக்கு உட்படுத்தப்படும்.',
  'welcome_to_greenfield_heights_community': 'கிரீன்ஃபீல்ட் ஹைட்ஸ் சமூகத்திற்கு வரவேற்கிறோம்',
  'we_are_delighted_to_welcome_all_residents_please_reach_out_to_management_for_any_facility_requests': 'அனைத்து குடியிருப்பாளர்களையும் வரவேற்பதில் நாங்கள் மகிழ்ச்சியடைகிறோம்! எந்தவொரு வசதி கோரிக்கைகளுக்கும் நிர்வாகத்தைத் தொடர்பு கொள்ளவும்.',
  'pool_maintenance_20_july_2026': 'நீச்சல் குளம் பராமரிப்பு – 20 ஜூலை 2026',
  'the_swimming_pool_will_remain_closed_on_20th_july_2026_for_annual_chlorination_and_tile_maintenance_we_apologize_for_the_inconvenience': 'வருடாந்திர குளோரினேஷன் மற்றும் டைல் பராமரிப்புக்காக 20 ஜூலை 2026 அன்று நீச்சல் குளம் மூடப்பட்டிருக்கும். சிரமத்திற்கு வருந்துகிறோம்.',
  'independence_day_celebration_15_august_2026': 'சுதந்திர தின விழா – 15 ஆகஸ்ட் 2026',
  'greenfield_heights_community_cordially_invites_all_residents_to_the_independence_day_celebration_at_the_clubhouse_main_hall_at_8_00_am': 'கிரீன்ஃபீல்ட் ஹைட்ஸ் சமூகம் அனைத்து குடியிருப்பாளர்களையும் காலை 8:00 மணிக்கு கிளப்ஹவுஸ் மெயின் ஹாலில் நடைபெறும் சுதந்திர தின கொண்டாட்டத்திற்கு அன்புடன் அழைக்கிறது.',
  'scheduled_power_outage_18_july_2026_block_b': 'திட்டமிடப்பட்ட மின் தடை – 18 ஜூலை 2026 (பிளாக் B)',
  'electrical_board_maintenance_scheduled_for_block_b_apartments_on_18_july_between_10_am_2_pm_generator_backup_will_be_available_for_common_areas': 'பிளாக் B குடியிருப்புகளுக்கான மின் வாரிய பராமரிப்பு ஜூலை 18 அன்று காலை 10 மணி முதல் மதியம் 2 மணி வரை திட்டமிடப்பட்டுள்ளது. பொதுவான பகுதிகளுக்கு ஜெனரேட்டர் பேக்கப் கிடைக்கும்.',
  'monthly_agm_25_july_2026': 'மாதாந்திர பொதுக் கூட்டம் – 25 ஜூலை 2026',
  'annual_general_meeting_for_q2_2026_financial_review_agenda_budget_approval_security_upgrade_proposal_amenity_booking_policy_update': 'Q2 2026 நிதி மறுஆய்வுக்கான வருடாந்திர பொதுக் கூட்டம். நிகழ்ச்சி நிரல்: பட்ஜெட் ஒப்புதல், பாதுகாப்பு மேம்பாட்டு திட்டம், வசதி முன்பதிவு கொள்கை புதுப்பிப்பு.',
  'lift_inspection_block_c_22_july_2026': 'லிஃப்ட் ஆய்வு – பிளாக் C – 22 ஜூலை 2026',
  'government_mandated_elevator_inspection_for_block_c_lifts_expected_completion_4_hours_stairways_accessible_at_all_times': 'பிளாக் C லிஃப்ட்களுக்கான அரசு கட்டாய லிஃப்ட் ஆய்வு. எதிர்பார்க்கப்படும் நிறைவு: 4 மணி நேரம். படிக்கட்டுகள் எப்போதும் பயன்படுத்தக்கூடியவை.',
  'new_visitor_parking_policy': 'புதிய பார்வையாளர் பார்க்கிங் கொள்கை',
  'effective_1_august_2026_visitor_parking_is_limited_to_2_hours_per_visit_between_9_am_and_9_pm_residents_must_pre_register_visitors_via_the_portal': '1 ஆகஸ்ட் 2026 முதல், காலை 9 மணி முதல் இரவு 9 மணி வரை ஒரு வருகைக்கு பார்வையாளர் பார்க்கிங் 2 மணிநேரமாக வரையறுக்கப்பட்டுள்ளது. குடியிருப்பாளர்கள் போர்டல் வழியாக பார்வையாளர்களை முன்கூட்டியே பதிவு செய்ய வேண்டும்.',
  'fitness_center_new_timings': 'உடற்பயிற்சி மையத்தின் புதிய நேரங்கள்',
  'starting_1_august_the_fitness_center_will_be_open_5_am_11_pm_on_weekdays_and_6_am_10_pm_on_weekends_personal_trainers_available_on_sat_sun': 'ஆகஸ்ட் 1 முதல், உடற்பயிற்சி மையம் வார நாட்களில் காலை 5 மணி முதல் இரவு 11 மணி வரையிலும், வார இறுதி நாட்களில் காலை 6 மணி முதல் இரவு 10 மணி வரையிலும் திறந்திருக்கும். சனி & ஞாயிறுகளில் தனிப்பட்ட பயிற்சியாளர்கள் இருப்பார்கள்.',
  'water_conservation_drive_july_2026': 'நீர் பாதுகாப்பு இயக்கம் – ஜூலை 2026',
  'we_are_partnering_with_the_local_municipality_for_a_water_conservation_initiative_please_report_leakages_immediately_and_avoid_unnecessary_usage_between_2_pm_5_pm': 'நீர் பாதுகாப்பு முன்முயற்சிக்காக நாங்கள் உள்ளூர் நகராட்சியுடன் இணைந்து செயல்படுகிறோம். கசிவுகள் குறித்து உடனடியாக புகாரளிக்கவும், மதியம் 2 மணி முதல் மாலை 5 மணி வரை தேவையற்ற பயன்பாட்டைத் தவிர்க்கவும்.',
