  // Community Polls & Notices Seed Content
  'poll_q_clubhouse_gym': 'கிளப்ஹவுஸ் உடற்பயிற்சி மையத்தை புதிய உபகரணங்களுடன் மேம்படுத்த வேண்டுமா?',
